//! `levels/ffa_clock.lvl` (generated by `scripts/gen_clock_level.py`): THE CLOCKWORK, a 54 m octagonal brick drum 210 m tall.
//! Pinned: floating (no ground), almost totally destructible, a switchback spiral of landings and 23 degree ramps that is ONE
//! walkable network holding every spawn, hook-only places (free cogs, column cap, pendulums), hook anchors everywhere,
//! supported pickups, engine limits.

use shinobi_sim::character::{Cfg, PhysicsWorld};
use shinobi_sim::level::{is_floating, parse_level_file, LevelBox, LevelFile};
use shinobi_sim::power::PowerKind;
use shinobi_sim::pvp::KILL_PLANE_Y;
use shinobi_sim::rapier3d::prelude::*;
use std::collections::{HashMap, VecDeque};

fn load() -> LevelFile {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../levels/ffa_clock.lvl");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    parse_level_file(&text).unwrap_or_else(|e| panic!("ffa_clock.lvl: {e}"))
}

fn world(l: &LevelFile) -> PhysicsWorld {
    let mut w = PhysicsWorld { bodies: RigidBodySet::new(), colliders: ColliderSet::new(), islands: IslandManager::new(), queries: QueryPipeline::new() };
    l.level.insert_into(&mut w);
    w.queries.update(&w.colliders);
    w
}

fn inside(b: &LevelBox, p: [f32; 3]) -> bool {
    let (s, c) = b.rot_z.sin_cos();
    let (dx, dy) = (p[0] - b.center[0], p[1] - b.center[1]);
    let (u, v) = (dx * c + dy * s, -dx * s + dy * c);
    u.abs() <= b.half[0] && v.abs() <= b.half[1] && (p[2] - b.center[2]).abs() <= b.half[2]
}

/// Top face of one box at (x, z) (rolled boxes give their slope).
fn surface_at(b: &LevelBox, x: f32, z: f32) -> Option<f32> {
    if (z - b.center[2]).abs() > b.half[2] {
        return None;
    }
    let (s, c) = b.rot_z.sin_cos();
    let u = (x - b.center[0] + b.half[1] * s) / c;
    (u.abs() <= b.half[0]).then(|| b.center[1] + u * s + b.half[1] * c)
}

fn d3(a: [f32; 3], b: [f32; 3]) -> f32 {
    ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

fn box_dist(b: &LevelBox, p: [f32; 3]) -> f32 {
    let (s, c) = b.rot_z.sin_cos();
    let (dx, dy, dz) = (p[0] - b.center[0], p[1] - b.center[1], p[2] - b.center[2]);
    let (u, v) = (dx * c + dy * s, -dx * s + dy * c);
    let (ex, ey, ez) = ((u.abs() - b.half[0]).max(0.0), (v.abs() - b.half[1]).max(0.0), (dz.abs() - b.half[2]).max(0.0));
    (ex * ex + ey * ey + ez * ez).sqrt()
}

#[test]
fn clockwork_counts_spawns_pickups_and_bands() {
    let l = load();
    assert!((1200..=1800).contains(&l.level.boxes.len()), "{} boxes", l.level.boxes.len());
    assert!((14..=18).contains(&l.level.spawns.len()), "{} spawns", l.level.spawns.len());
    let bands: std::collections::BTreeSet<i32> = l.level.spawns.iter().map(|s| (s[1] / 30.0).floor() as i32).collect();
    assert!(bands.len() >= 5, "spawns span only {} 30 m height bands", bands.len());
    let cubes = l.pickups.iter().filter(|p| p.kind == PowerKind::None).count();
    let yumi: Vec<_> = l.pickups.iter().filter(|p| p.kind == PowerKind::Yumi).collect();
    let tags = l.pickups.iter().filter(|p| p.kind == PowerKind::Tag).count();
    assert_eq!(cubes, 6, "{cubes} cubes");
    assert_eq!(yumi.len(), 2, "{} bows", yumi.len());
    assert_eq!(tags, 4, "{tags} tag bags");
    assert!(yumi.iter().all(|p| p.pos[1] > 195.0), "bows sit on the column cap");
    assert!(l.pickups.iter().filter(|p| p.kind != PowerKind::None).all(|p| p.respawn_secs == 45.0));
}

#[test]
fn destructible_share_by_volume_is_at_least_70_percent_and_bricks_are_2_to_6_m() {
    let l = load();
    let vol = |b: &LevelBox| 8.0 * b.half[0] * b.half[1] * b.half[2];
    let total: f32 = l.level.boxes.iter().map(vol).sum();
    let dest: f32 = l.level.boxes.iter().filter(|b| b.hp > 0.0).map(vol).sum();
    assert!(dest / total >= 0.70, "only {:.0}% of the volume is destructible", 100.0 * dest / total);
    // bedrock stays a thin core: under spawns and pedestals only
    let perm = l.level.boxes.iter().filter(|b| b.hp <= 0.0).count();
    assert!(perm <= l.level.spawns.len() + l.pickups.len() + 4, "{perm} permanent boxes");
    for b in l.level.boxes.iter().filter(|b| b.rot_z == 0.0 && b.hp > 0.0) {
        let long = b.half.iter().map(|h| 2.0 * h).fold(0.0f32, f32::max);
        assert!(long <= 6.01, "brick {b:?} is {long} m long");
    }
}

#[test]
fn there_is_no_ground_the_drum_is_over_200_m_tall_and_the_kill_plane_is_far_below() {
    let l = load();
    assert!(is_floating(&l.level), "no box may reach down toward y = 0");
    let lowest = l.level.boxes.iter().map(|b| b.center[1] - b.half[1]).fold(f32::MAX, f32::min);
    assert!(lowest >= 8.0 - 1e-3 && lowest - KILL_PLANE_Y >= 28.0, "lowest body y = {lowest}, kill plane {KILL_PLANE_Y}");
    assert_eq!(l.level.floor_half(), None, "no floor slab");
    let top = l.level.boxes.iter().map(|b| b.center[1] + b.half[1]).fold(0.0, f32::max);
    assert!(top - lowest >= 200.0, "the drum is only {} m tall", top - lowest);
}

#[test]
fn spawns_stand_on_a_deck_clear_of_geometry_and_not_stacked() {
    let l = load();
    let cfg = Cfg::default();
    let reach = cfg.half_height + cfg.radius;
    for s in &l.level.spawns {
        for dy in [-reach + 0.05, -0.3, 0.0, 0.3, reach - 0.05] {
            for (ox, oz) in [(0.0, 0.0), (cfg.radius, 0.0), (-cfg.radius, 0.0), (0.0, cfg.radius), (0.0, -cfg.radius)] {
                let p = [s[0] + ox, s[1] + dy, s[2] + oz];
                assert!(!l.level.boxes.iter().any(|b| inside(b, p)), "spawn {s:?}: capsule point {p:?} is inside geometry");
            }
        }
        // standing room overhead
        for dy in [reach + 0.2, 3.0] {
            assert!(!l.level.boxes.iter().any(|b| inside(b, [s[0], s[1] + dy, s[2]])), "spawn {s:?} has no headroom");
        }
        let top = l.level.boxes.iter().filter_map(|b| surface_at(b, s[0], s[2])).filter(|h| (*h - (s[1] - reach)).abs() < 0.1).count();
        assert!(top >= 1, "spawn {s:?} floats or is buried");
    }
    let n = l.level.spawns.len();
    let nearest: Vec<f32> = (0..n).map(|i| (0..n).filter(|j| *j != i).map(|j| d3(l.level.spawns[i], l.level.spawns[j])).fold(f32::MAX, f32::min)).collect();
    let min = nearest.iter().copied().fold(f32::MAX, f32::min);
    assert!(min >= 9.0, "two spawns only {min:.1} m apart");
}

/// Flood a 1 m grid of EVERY walkable surface (the drum stacks floors over floors, so one height per cell is not enough): a node
/// is (cell, surface height); neighbours join when the surfaces differ by <= 0.5 m and nothing solid fills the 1.8 m above.
/// All spawns lie in ONE component that reaches the top landing, mated cogs and the tag bags; free cogs, the cap and the
/// pendulum tops are off it (hook only).
#[test]
fn one_walkable_network_joins_every_spawn_and_the_high_places_stay_hook_only() {
    let l = load();
    let half = 36i32;
    let mut cells: HashMap<(i32, i32), Vec<f32>> = HashMap::new();
    for x in -half..half {
        for z in -half..half {
            let (px, pz) = (x as f32 + 0.5, z as f32 + 0.5);
            let mut hs: Vec<f32> = Vec::new();
            for b in &l.level.boxes {
                if let Some(h) = surface_at(b, px, pz) {
                    let blocked = l.level.boxes.iter().any(|o| inside(o, [px, h + 0.9, pz]) || inside(o, [px, h + 1.7, pz]));
                    if !blocked && !hs.iter().any(|g| (g - h).abs() < 0.05) {
                        hs.push(h);
                    }
                }
            }
            if !hs.is_empty() {
                cells.insert((x, z), hs);
            }
        }
    }
    let cell_of = |p: [f32; 3]| (p[0].floor() as i32, p[2].floor() as i32);
    let key = |h: f32| (h * 10.0).round() as i32;
    let node = |p: [f32; 3]| {
        let c = cell_of(p);
        let base = p[1] - 0.81;
        let h = cells[&c].iter().copied().min_by(|a, b| (a - base).abs().partial_cmp(&(b - base).abs()).unwrap()).unwrap();
        (c, key(h))
    };
    let start = node(l.level.spawns[0]);
    let mut seen: std::collections::HashSet<((i32, i32), i32)> = std::collections::HashSet::new();
    let mut q = VecDeque::from([start]);
    seen.insert(start);
    while let Some(((x, z), hy)) = q.pop_front() {
        let y = hy as f32 / 10.0;
        for (dx, dz) in [(1, 0), (-1, 0), (0, 1), (0, -1)] {
            let c = (x + dx, z + dz);
            if let Some(hs) = cells.get(&c) {
                for &h in hs {
                    if (h - y).abs() <= 0.5 {
                        let n = (c, key(h));
                        if seen.insert(n) {
                            q.push_back(n);
                        }
                    }
                }
            }
        }
    }
    for s in &l.level.spawns {
        assert!(seen.contains(&node(*s)), "spawn {s:?} is not on the walkable network");
    }
    for p in l.pickups.iter().filter(|p| p.kind == PowerKind::Tag || p.kind == PowerKind::None) {
        let n = node([p.pos[0], p.pos[1] - 0.19, p.pos[2]]);
        assert!(seen.contains(&n), "pickup {:?} cannot be walked to", p.pos);
    }
    let top_reach = seen.iter().map(|n| n.1).max().unwrap() as f32 / 10.0;
    assert!(top_reach >= 190.0, "the spiral only walks up to y {top_reach}");
    let bands: std::collections::BTreeSet<i32> = seen.iter().map(|n| n.1 / 400).collect();
    assert!(bands.len() >= 5, "the network spans only {} 40 m bands", bands.len());
    // hook-only: surfaces above y 40 that the flood never reached (free cogs, column cap, pendulum bobs, wall balconies)
    let off: usize = cells.iter().map(|(c, hs)| hs.iter().filter(|h| **h > 40.0 && **h < 205.0 && !seen.contains(&(*c, key(**h)))).count()).sum();
    assert!(off >= 300, "only {off} high surface cells are off the walkable network");
    let cap = (-5..5).flat_map(|x| (-5..5).map(move |z| (x, z))).filter(|c| cells.get(c).map_or(false, |hs| hs.iter().any(|h| (*h - 200.0).abs() < 0.01) && !seen.contains(&(*c, 2000)))).count();
    assert!(cap >= 80, "the column cap must be off the network ({cap} cells)");
}

/// Hook anchors: from every free point of the drum's volume (8 m grid, y 20..200) at least three distinct boxes lie within 30 m.
#[test]
fn hook_anchors_are_within_30_m_of_anywhere_inside_the_drum() {
    let l = load();
    let mut worst = usize::MAX;
    let mut y = 20.0f32;
    while y <= 200.0 {
        for x in (-24..=24).step_by(8) {
            for z in (-24..=24).step_by(8) {
                let p = [x as f32, y, z as f32];
                if l.level.boxes.iter().any(|b| inside(b, p)) {
                    continue;
                }
                let n = l.level.boxes.iter().filter(|b| box_dist(b, p) <= 30.0).count();
                worst = worst.min(n);
            }
        }
        y += 10.0;
    }
    assert!(worst >= 3, "a point of the drum has only {worst} anchors within 30 m");
}

#[test]
fn wall_run_faces_ramps_and_pendulums_exist() {
    let l = load();
    // the drum wall: a column of 6 m bricks makes a 200 m face
    let n = l.level.boxes.iter().filter(|b| b.rot_z == 0.0 && b.center[0].abs() < 3.5 && b.center[2] > 29.0 && b.half[1] == 3.0).count();
    assert!(n >= 30, "{n} bricks in the north wall's middle column");
    let ramps = l.level.boxes.iter().filter(|b| b.rot_z != 0.0).count();
    assert!(ramps >= 80, "{ramps} ramp pieces");
    for b in l.level.boxes.iter().filter(|b| b.rot_z != 0.0) {
        assert!(b.rot_z.abs() <= 24.0f32.to_radians(), "ramp {b:?} too steep");
    }
    let bobs = l.level.boxes.iter().filter(|b| b.half == [3.0, 3.0, 3.0] && b.center[1] > 190.0 && b.center[1] < 200.0 && b.center[0].abs() > 5.0 && b.center[0].abs() < 12.0 && b.center[2].abs() < 12.0).count();
    assert_eq!(bobs, 4, "{bobs} pendulum bobs");
}

#[test]
fn pickups_are_supported_and_not_inside_geometry() {
    let l = load();
    for p in &l.pickups {
        assert!(!l.level.boxes.iter().any(|b| inside(b, p.pos)), "pickup {:?} is inside geometry", p.pos);
        let under = l.level.boxes.iter().find(|b| surface_at(b, p.pos[0], p.pos[2]).map_or(false, |h| (p.pos[1] - h - 1.0).abs() < 0.3));
        let under = under.unwrap_or_else(|| panic!("pickup {:?} is not ~1 m above a surface", p.pos));
        assert!(under.hp <= 0.0, "pedestal under {:?} must be permanent", p.pos);
    }
}

#[test]
fn engine_numeric_limits_cover_the_map() {
    let l = load();
    let far = l.level.boxes.iter().map(|b| b.center[0].abs() + b.half[0]).chain(l.level.boxes.iter().map(|b| b.center[2].abs() + b.half[2])).fold(0.0, f32::max);
    assert!(far <= 125.0, "geometry reaches {far} m sideways");
    let q = shinobi_proto::quant::q_pos3([2.0 * far, 215.0, 2.0 * far]);
    let back = shinobi_proto::quant::dq_pos3(q);
    assert!((back[0] - 2.0 * far).abs() < 0.01 && (back[1] - 215.0).abs() < 0.01, "q_pos3 loses precision");
    let w = world(&l);
    assert_eq!(w.colliders.len(), l.level.boxes.len());
}
